    # n=3 on an 11x11 grid, n=4 on a 19x19 grid, and in general
    # dimension = n*tile_size + (n-1).
    n = next((k for k in range(1, min(h, w) + 1)
              if h == w and (h + 1) % (k + 1) == 0
              and ((h + 1) // (k + 1)) >= 1), None)
    if n is None:
        return out
    tile_size = (h + 1) // (n + 1)
    stride = tile_size + 1
    if n * tile_size + (n - 1) != h:
        return out

    def tile(r, c, source=grid):
        r0, c0 = r * stride, c * stride
        return [source[r0 + dr][c0:c0 + tile_size] for dr in range(tile_size)]

